theme.css:
/* theme: Fractured Circuit | A day of broken institutions and shattered markets, where every line of defense — courts, markets, reputations — is being stormed or gutted. */
/* mood: bad */
/* layout: hero=poster; political-news=outline/feature; financial-news=stat/grid-2; entertainment-news=tile/masonry; sports=numbered/grid-2; music-releases=plain/stack; stock-analysis=timeline/grid-2; outlook=plain/stack */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #281012;
  --ink: #f5e9ea;
  --ink-soft: #d8bec6;
  --muted: #a77d86;
  --accent: #ff4141;
  --accent-ink: #1c0b0d;
  --rule: #4d1d22;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

.diary-page {
  background: var(--paper);
  color: var(--ink-soft);
  font-family: var(--font-body);
}

/* ——— Hero: brutalist poster with signal-red band ——— */
.diary-page .diary-hero {
  background: var(--accent);
  border-bottom: 4px solid var(--ink);
}

.diary-page[data-hero="poster"] .diary-hero-inner {
  padding-block: 3rem 4rem;
  max-width: 76rem;
}

.diary-page[data-hero="poster"] .diary-hero-inner .diary-kicker {
  margin-top: 1.5rem;
  font-family: var(--font-ui);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-hero-inner .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 9vw, 6.5rem);
  line-height: 0.88;
  text-transform: uppercase;
  max-width: 90%;
  margin-top: 1.2rem;
  letter-spacing: -0.02em;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-hero-inner .diary-summary {
  font-family: var(--font-body);
  font-size: clamp(1.1rem, 1.8vw, 1.4rem);
  line-height: 1.6;
  max-width: 42ch;
  margin-top: 1.5rem;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-hero-inner .diary-theme-note {
  margin-top: 1.5rem;
  color: var(--accent-ink);
  font-family: var(--font-ui);
  font-size: 0.85rem;
}

.diary-page[data-hero="poster"] .diary-hero-inner .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
}

.diary-page .diary-hero .diary-crumbs a {
  color: var(--accent-ink);
}

/* ——— Body grid & TOC ——— */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    background: none;
    border: 0;
  }

  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* ——— Section structure with fractured title edges ——— */
.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 2.75rem;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
  align-items: end;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.75rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 2.2rem;
  font-weight: 400;
  line-height: 0.8;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
}

/* ——— Card: outline with hard corners & red top notch ——— */
.diary-page .diary-card--outline .diary-card-inner {
  border: 2px solid var(--rule);
  border-radius: 0;
  padding: 1.5rem 1.5rem 1.75rem;
  position: relative;
}

.diary-page .diary-card--outline .diary-card-inner::before {
  content: "";
  position: absolute;
  top: -2px;
  left: -2px;
  width: 3rem;
  height: 2px;
  background: var(--accent);
}

.diary-page .diary-card--outline .diary-card-title {
  font-size: 1.3rem;
  line-height: 1.15;
  padding-right: 0.5rem;
}

/* ——— Card: tile — red-tinted fractured panel ——— */
.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.5rem;
  position: relative;
}

.diary-page .diary-card--tile .diary-card-inner::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 4px;
  background: repeating-linear-gradient(
    90deg,
    var(--accent) 0 12px,
    transparent 12px 24px
  );
}

/* ——— Card: numbered — oversized stencil indices ——— */
.diary-page .diary-card--numbered .diary-card-inner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1rem;
  row-gap: 0.6rem;
  align-content: start;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.2rem;
  font-weight: 400;
  line-height: 0.8;
  color: var(--accent);
}

/* ——— Card: stat — heavy red rule with oversized figure ——— */
.diary-page .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 0.75rem;
}

.diary-page .diary-card--stat .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 12cqi, 4rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  color: var(--accent);
}

/* ——— Card: timeline — blood-red rail with pulse dot ——— */
.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 1.9rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper), 0 0 12px var(--accent);
}

/* ——— Card: plain — but with red continuation bar ——— */
.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top: 1px solid var(--rule);
  padding-top: 1.75rem;
}

/* ——— Card titles ——— */
.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 1.1;
  font-size: 1.35rem;
}

/* ——— Body prose — tips of red over muted body ——— */
.diary-page .diary-card-body {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
  font-family: var(--font-ui);
  font-weight: 600;
  letter-spacing: 0.06em;
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose hr {
  border-top-color: var(--rule);
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

/* ——— Drop cap in first section — fracture it ——— */
@media (min-width: 768px) {
  .diary-page .diary-section:first-child .diary-card--outline:first-child .diary-prose > p:first-of-type::first-letter {
    float: left;
    margin: 0.06em 0.12em 0 0;
    font-family: var(--font-display);
    font-size: 3.8em;
    font-weight: 400;
    line-height: 0.75;
    padding: 0.05em 0.15em;
    background: var(--accent);
    color: var(--accent-ink);
  }
}

/* ——— Threads chip — red outline, aggressive ——— */
.diary-page .diary-card-thread {
  border: 1px solid var(--accent);
  color: var(--accent);
  background: transparent;
  border-radius: 0;
  letter-spacing: 0.04em;
  font-weight: 600;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* ——— Markets — dark red fact board ——— */
.diary-page .diary-markets-label {
  color: var(--muted);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark-change.is-down {
  color: var(--accent);
}

/* ——— Footer — red seam ——— */
.diary-page .diary-footer {
  border-top: 2px solid var(--accent);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* ——— Layout: feature — first card gets red slab, rest remain two-col ——— */
@media (min-width: 40rem) {
  .diary-page .diary-stories--feature {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.diary-page .diary-stories--feature > .diary-card:first-child {
  grid-column: 1 / -1;
}

.diary-page .diary-stories--feature > .diary-card:first-child .diary-card-inner {
  border-left: 6px solid var(--accent);
  padding-left: 1.25rem;
}

/* ——— Layout: masonry — tiles gain staggered red fragments ——— */
.diary-page .diary-stories--masonry .diary-card--tile:nth-child(even) .diary-card-inner {
  margin-top: 0.75rem;
}

.diary-page .diary-stories--masonry .diary-card--tile:nth-child(odd) .diary-card-inner {
  margin-top: 0;
}

/* ——— Grid fine-tuning — section skeletons ——— */
.diary-page [data-section="political-news"] .diary-stories--feature > .diary-card:first-child .diary-card-body {
  font-size: 1.2rem;
  line-height: 1.75;
}

/* ——— Subtle entrance — cards crack into view once ——— */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-card {
    animation: diary-crack-in 400ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  .diary-page .diary-card:nth-child(2) {
    animation-delay: 60ms;
  }

  .diary-page .diary-card:nth-child(3) {
    animation-delay: 120ms;
  }

  .diary-page .diary-card:nth-child(4) {
    animation-delay: 180ms;
  }

  .diary-page .diary-card:nth-child(5) {
    animation-delay: 240ms;
  }

  .diary-page .diary-card:nth-child(6) {
    animation-delay: 300ms;
  }
}

@keyframes diary-crack-in {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
    clip-path: polygon(0 0, 100% 0, 100% 0, 0 0);
  }
  to {
    opacity: 1;
    transform: none;
    clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%);
  }
}

/* ——— Loud halloween touch: section titles get a red tick ——— */
.diary-page .diary-section-title::before {
  content: "▪";
  color: var(--accent);
  font-size: 0.6em;
  margin-right: 0.25em;
  vertical-align: middle;
}

/* ——— Odd fragments: a dashed red rule under financial figures ——— */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-figure::after {
  content: "";
  display: block;
  margin-top: 0.25rem;
  height: 2px;
  background: repeating-linear-gradient(
    90deg,
    var(--accent) 0 6px,
    transparent 6px 12px
  );
}

/* ——— Prose lists in cards get tight red dashes ——— */
.diary-page .diary-prose ul > li {
  padding-left: 1.1rem;
}

.diary-page .diary-prose ul > li::before {
  width: 0.5rem;
  background: var(--accent);
}

/* ——— No rounded softness anywhere; all corners stay square ——— */
.diary-page .diary-toc,
.diary-page .diary-hero,
.diary-page .diary-card-inner,
.diary-page .diary-spark,
.diary-page .diary-theme-name {
  border-radius: 0 !important;
}
